    typealias SwiftType = DocumentCoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DocumentCoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ConfigurationError(
            details: try FfiConverterString.read(from: &buf)
            )
        case 2: return .FileBrokerFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 3: return .PasswordRequired
        case 4: return .InvalidPdf(
            details: try FfiConverterString.read(from: &buf)
            )
        case 5: return .SessionNotFound(
            sessionId: try FfiConverterString.read(from: &buf)
            )
        case 6: return .NavigationFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 7: return .TransactionFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 8: return .SaveFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 9: return .RecoveryFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 10: return .ImagingFailure(
            details: try FfiConverterString.read(from: &buf)
            )
        case 11: return .InternalFailure(
            details: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DocumentCoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .ConfigurationError(details):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .FileBrokerFailure(details):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(details, into: &buf)
            
        
        case .PasswordRequired:
            writeInt(&buf, Int32(3))
        
        
        case let .InvalidPdf(details):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .SessionNotFound(sessionId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(sessionId, into: &buf)
            
        
        case let .NavigationFailure(details):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .TransactionFailure(details):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .SaveFailure(details):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .RecoveryFailure(details):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .ImagingFailure(details):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(details, into: &buf)
            
        
